# Micronutrient section, element data part A: zinc, iron, manganese, copper, boron.
# Plain language for farmers. Methods and sources only: no dose numbers (doses come from the soil test,
# the product label or the local agriculture officer / KVK). Every symptom list is general guidance;
# the pages say to confirm with a soil or leaf test.

def P(t): return ("html", f"<p>{t}</p>")
def T(head, rows):
    th = "".join(f"<th>{h}</th>" for h in head)
    tr = "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows)
    return ("html", f'<div class="tablewrap"><table class="packs"><thead><tr>{th}</tr></thead><tbody>{tr}</tbody></table></div>')

